fn countVowels(text: Text) -> Number {
    var count = 0
    var vowels = ["a", "e", "i", "o", "u"]
    for ch in text.lower().chars() {
        if vowels.contains(ch) {
            count = count + 1
        }
    }
    return count
}

test "countVowels basic behavior" {
  expect countVowels("hello") == 2
  expect countVowels("AEIOU") == 5
  expect countVowels("sky") == 0
  expect countVowels("Banana") == 3
  expect countVowels("") == 0
}

