fn reverseWords(sentence: Text) -> Text {
    // Split on spaces
    let parts = sentence.split(" ")
    var words: Text[] = []
    for w in parts {
        if w != "" {
            words.append(w)
        }
    }

    // Reverse the words list
    var reversed: Text[] = []
    var i = words.length() - 1
    while i >= 0 {
        reversed.append(words[i])
        i = i - 1
    }

    // Join reversed words with a single space
    var result = ""
    var first = true
    for w in reversed {
        if first {
            result = w
            first = false
        } else {
            result = result + " " + w
        }
    }
    return result
}

test "reverseWords basic and edge cases" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("one two three") == "three two one"
  expect reverseWords("  leading and trailing  ") == "trailing and leading"
  expect reverseWords("") == ""
  expect reverseWords("single") == "single"
}

fn reverseWords(sentence: Text) -> Text {
    var words: Text[] = []
    var current = ""
    for i in 0..=sentence.length() {
        var ch = ""
        if i < sentence.length() {
            ch = sentence.substring(i, i + 1)
        }
        if ch == " " or ch == "" {
            if current != "" {
                words.append(current)
                current = ""
            }
        } else {
            current = current + ch
        }
    }
    var reversed: Text[] = []
    var i = words.length() - 1
    while i >= 0 {
        reversed.append(words[i])
        i = i - 1
    }
    var result = ""
    for i in 0..=reversed.length() {
        if i < reversed.length() {
            if i == 0 {
                result = reversed[i]
            } else {
                result = result + " " + reversed[i]
            }
        }
    }
    return result
}

test "the ask's own tests" {
  expect reverseWords("the quick brown fox") == "fox brown quick the"
  expect reverseWords("  hello   world  ") == "world hello"
  expect reverseWords("") == ""
  expect reverseWords("single") == "single"
  expect reverseWords("   a  b   c   ") == "c b a"
}

fn fizzBuzz(n: Number) -> Text {
  if n % 3 == 0 and n % 5 == 0 {
    return "fizzbuzz"
  } else if n % 3 == 0 {
    return "fizz"
  } else if n % 5 == 0 {
    return "buzz"
  }
  return n.to_text()
}

test "fizzBuzz function" {
  expect fizzBuzz(3) == "fizz"
  expect fizzBuzz(5) == "buzz"
  expect fizzBuzz(15) == "fizzbuzz"
  expect fizzBuzz(7) == "7"
  expect fizzBuzz(0) == "fizzbuzz"
}

fn isPrime(n: Number) -> Bool {
    if n < 2 {
        return false
    }
    if n == 2 {
        return true
    }
    if n % 2 == 0 {
        return false
    }
    var i = 3
    while i * i <= n {
        if n % i == 0 {
            return false
        }
        i = i + 2
    }
    return true
}

test "the ask's own tests" {
  expect isPrime(5) == true
  expect isPrime(4) == false
  expect isPrime(2) == true
  expect isPrime(1) == false
  expect isPrime(0) == false
  expect isPrime(-7) == false
}

