fn generate_html_template(title: Text, projects: Text[]) -> Text {
    var list_items = ""
    for project in projects {
        list_items = list_items + "<li>" + project + "</li>"
    }
    let html = "<html><head><title>" + title + "</title></head><body><ul>" + list_items + "</ul></body></html>"
    return html
}

test "generate_html_template" {
  expect generate_html_template("My Site", ["Project A", "Project B"]) == "<html><head><title>My Site</title></head><body><ul><li>Project A</li><li>Project B</li></ul></body></html>"
  expect generate_html_template("Empty", []) == "<html><head><title>Empty</title></head><body><ul></ul></body></html>"
  expect generate_html_template("Single", ["Only"]) == "<html><head><title>Single</title></head><body><ul><li>Only</li></ul></body></html>"
}

fn get_topic(day: Text) -> Text {
  let d = day.lower()
  if d == "monday" { return "Set Theory" }
  else if d == "tuesday" { return "Logic" }
  else if d == "wednesday" { return "Functions" }
  else if d == "thursday" { return "Relations" }
  else if d == "friday" { return "Graph Theory" }
  else { return "" }
}

test "schedule mapping" {
  expect get_topic("Monday") == "Set Theory"
  expect get_topic("Tuesday") == "Logic"
  expect get_topic("Wednesday") == "Functions"
  expect get_topic("Thursday") == "Relations"
  expect get_topic("Friday") == "Graph Theory"
  expect get_topic("") == ""
}

